package gin

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"testing"
)

func probeOne(t *testing.T, name string, routes []string, paths []string) {
	engine := New()
	var captured string
	var matched string
	for _, r := range routes {
		rr := r
		engine.GET(rr, func(c *Context) { captured = fmt.Sprintf("%v", c.Params); matched = rr })
	}
	for _, p := range paths {
		captured, matched = "", ""
		w := httptest.NewRecorder()
		req, _ := http.NewRequest("GET", p, nil)
		func() {
			defer func() {
				if e := recover(); e != nil {
					t.Logf("[%s] PANIC %s: %v", name, p, e)
				}
			}()
			engine.ServeHTTP(w, req)
		}()
		t.Logf("[%s] path=%-16s code=%d matched=%-16s params=%s", name, p, w.Code, matched, captured)
	}
}

