package gin

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestZZProbeNegotiate(t *testing.T) {
	cases := []struct {
		accept string
		offers []string
	}{
		{"text/html", []string{"text"}},
		{"text/html", []string{"text/html"}},
		{"text/html", []string{"text/*"}},
		{"text/html", []string{"application/json", "text/html"}},
		{"text/*", []string{"text"}},
		{"*/*", []string{"text"}},
		{"application/xml;q=0.9", []string{"application/xml"}},
		{"text/html,application/xhtml+xml,application/xml;q=0.9;q=0.8", []string{"application/json", "application/xml"}},
		{"text/html,application/xhtml+xml,application/xml;q=0.9;q=0.8", []string{"application/xml", "text/html"}},
		{"text/html", []string{"text/htm"}},
		{"text/htm", []string{"text/html"}},
	}
	for _, tc := range cases {
		c, _ := CreateTestContext(httptest.NewRecorder())
		c.Request, _ = http.NewRequest("POST", "/", nil)
		c.Request.Header.Add("Accept", tc.accept)
		func() {
			defer func() {
				if e := recover(); e != nil {
					t.Logf("accept=%-50q offers=%-40q PANIC: %v", tc.accept, tc.offers, e)
				}
			}()
			t.Logf("accept=%-50q offers=%-40q -> %q", tc.accept, tc.offers, c.NegotiateFormat(tc.offers...))
		}()
	}
}
EOF
